"""Compare the user-selected top mounting row before/after local capping."""
import argparse,json
from pathlib import Path


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('out',type=Path);a=ap.parse_args();out=a.out.resolve();s=json.loads((out/'summary.json').read_bytes());views=['oblique','mouth','reverse','top','bottom','front','back'];images={v:{stage:str(out/f'{stage}-{v}.png') for stage in ['before','after']} for v in views}
    html='''<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px var(--font-sans,system-ui);color:var(--foreground,#ddd);margin:0}p{line-height:1.5;color:var(--muted-foreground,#999)}b{color:var(--foreground,#ddd)}select{font:inherit;padding:5px;background:var(--card,#222);color:var(--foreground,#ddd);border:1px solid var(--border,#444);border-radius:5px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}figure{margin:0}img{width:100%;border-radius:5px}figcaption{font-size:12px;color:var(--muted-foreground,#999);margin-top:5px}.stats{display:flex;gap:28px;margin:18px 0;flex-wrap:wrap}.stats b{display:block;font-size:23px}small{color:var(--muted-foreground,#999);line-height:1.5}</style></head><body><p><b>The visible top mounting row is closed.</b> Ten stepped recesses lose their internal walls and shoulders. The two end holes have rim-matched visual caps; their more complex internal bosses remain behind the caps.</p><div class="stats"><div><b>BEFORE → AFTER</b>crossbar triangles</div><div><b>BASE</b>visual triangles / Base</div></div><label>View <select id="view">OPTIONS</select></label><div class="pair"><figure><img id="before" alt="Approved crossbar with mounting row"><figcaption>Previously approved crossbar</figcaption></figure><figure><img id="after" alt="Crossbar with top mounting holes capped"><figcaption>Top row closed</figcaption></figure></div><p><b>Unchanged triangles retain exact positions and colours.</b> The outline, markings and other equipment are preserved. This local edit removes REMOVED triangles and adds CAPS cap triangles; it avoids re-simplifying the entire bar.</p><small>Collision remains 16,857 triangles per Base. Source CAD and installed assets are unchanged. “Mouth” looks directly along the top cover’s normal. Comparison uses 7 isolated and 18 whole-Base fixed source-pose views; runtime PBR and moving poses are outside this review. Source geometry: DJI / RoboMaster.</small><script>const data=IMAGES;function show(){for(const stage of ['before','after'])document.getElementById(stage).src=data[document.getElementById('view').value][stage]}document.getElementById('view').onchange=show;show();</script></body></html>'''
    html=html.replace('BEFORE',f"{s['previous_crossbar_triangles']:,}").replace('AFTER',f"{s['crossbar_triangles']:,}").replace('BASE',f"{s['base_triangles']:,}").replace('REMOVED',str(s['local_mesh']['removed_triangles'])).replace('CAPS',str(s['local_mesh']['cap_triangles'])).replace('OPTIONS',''.join('<option>'+v+'</option>' for v in views)).replace('IMAGES',json.dumps(images));(out/'review.html').write_text(html)
if __name__=='__main__':main()
